.darma-loader-three-dots-flashing{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 3.7);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
  animation:darma-loader-three-dots-flashing-td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:calc(var(--loader-speed, 1s) / 2);
}
.darma-loader-three-dots-flashing::before,
.darma-loader-three-dots-flashing::after{
  content:"";
  position:absolute;
  top:0;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:inherit;
}
.darma-loader-three-dots-flashing::before{left:calc(var(--td-gap) * -1);}
.darma-loader-three-dots-flashing::after{left:var(--td-gap);}
.darma-loader-three-dots-flashing::before{animation:darma-loader-three-dots-flashing-td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:0s;background-color:var(--loader-color, #6366f1)}
.darma-loader-three-dots-flashing::after{animation:darma-loader-three-dots-flashing-td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:var(--loader-speed, 1s);background-color:var(--loader-color, #6366f1)}
@keyframes darma-loader-three-dots-flashing-td-flash{
  0%{background-color:var(--loader-color, #6366f1)}
  50%,100%{background-color:var(--loader-secondary-color, #a5b4fc)}
}

